const journalAnchor={bytes:fs.statSync(journalFile).size,prefixHash:h.digest('hex'),sequence:last.sequence,hash:last.hash},sourceAnchor={bytes:last.state.sourceBytes,prefixHash:last.state.sourcePrefixHash,sequence:last.state.sourceSequence,hash:last.state.sourceHash};
const savedAt=new Date().toISOString(),kind='settlement_portfolio_v2',snapshot={schemaVersion:1,kind,cohort:pointer.cohort,bankHash:pointer.bankHash,bankFileHash:sha(fs.readFileSync(path.join(dir,'bank.json'))),pointerHash:sha(fs.readFileSync(pointerFile)),savedAt,paperState:last.state.paper,report,journalAnchor,sourceAnchor};
