const manifest={schemaVersion:1,owner:'Codex',entries:[{kind,cohort:pointer.cohort,snapshotFile,snapshotFileHash:sha(fs.readFileSync(path.join(dir,snapshotFile))),pauseRecord}]};assert(!fs.existsSync(path.join(rt,'paper-comparison-pauses.json')));atomicJson(path.join(rt,'paper-comparison-pauses.json'),manifest);
