atomicJson('data/frozen-comparison-pause-20261006.json',{schemaVersion:1,observedAt:savedAt,cohort:pointer.cohort,bankHash:pointer.bankHash,pauseHash:checked.pauseHash,retainedRisk:checked.retainedRisk,valuationStatus:checked.valuationStatus,journalAnchor,sourceAnchor,officialReconciliationAffected:false,accountingReset:false,verified:true});console.log(JSON.stringify({cohort:pointer.cohort,paused:true,retainedRisk:checked.retainedRisk,officialAccountUnaffected:true}));
